package pe.cruzroja.convocatorias.enrollments.domain; import java.util.UUID; public class Enrollment {private final UUID id,volunteerId,calloutId; private EnrollmentStatus status=EnrollmentStatus.PENDIENTE; public Enrollment(UUID id,UUID volunteerId,UUID calloutId){if(id==null||volunteerId==null||calloutId==null)throw new IllegalArgumentException("Inscripción inválida");this.id=id;this.volunteerId=volunteerId;this.calloutId=calloutId;} private void change(EnrollmentStatus next){if(status.isFinal())throw new IllegalStateException("La inscripción está en un estado final");status=next;} public void confirm(){change(EnrollmentStatus.CONFIRMADA);} public void reject(){change(EnrollmentStatus.RECHAZADA);} public void cancel(){change(EnrollmentStatus.CANCELADA);} public UUID id(){return id;} public UUID volunteerId(){return volunteerId;} public UUID calloutId(){return calloutId;} public EnrollmentStatus status(){return status;} }
